-- ═══════════════════════════════════════════════════════════════════════════
--  01 — تحديث محتوى التخصصات السبعة ومحتوى الموقع
--  التاريخ: 9/10/2026
--
--  المصادر (ملف الجودة ISO 21001:2018):
--    ISO-GEN-SC-01  بيان النطاق            → أسماء التخصصات السبعة
--    ISO-COM-MN-01  دليل الطالب وولي الأمر → المواد لكل صف (الفصل 9) · المخاطر ومهمات الوقاية (7-2)
--                                            · التدريب بورش الشركة (7-5)
--    ISO-SAF-WI-01  تعليمات السلامة         → المحاذير الخاصة بكل ورشة
--    ISO-GEN-PC-03 · ISO-INF-DC-01          → طبيعة التدريب العملي والورش
--    ISO-INF-RG-04  حصر معدات المركز        → أنواع المعدات (بدون أعداد)
--
--  طريقة التشغيل: Supabase ▸ SQL Editor ▸ الصق الملف كاملاً ▸ Run
--  الملف يعمل داخل معاملة واحدة: إما ينجح كله أو لا يتغير شيء.
--  ويأخذ نسخة احتياطية أولاً (جداول تنتهي بـ _bk_20261009) — الاسترجاع في آخر الملف.
-- ═══════════════════════════════════════════════════════════════════════════

begin;

-- ① نسخة احتياطية من الوضع الحالي
create table if not exists public.specializations_bk_20261009 as table public.specializations;
create table if not exists public.study_plans_bk_20261009     as table public.study_plans;
create table if not exists public.subjects_bk_20261009        as table public.subjects;
create table if not exists public.site_settings_bk_20261009   as table public.site_settings;
create table if not exists public.posts_bk_20261009           as table public.posts;
-- النسخ الاحتياطية لا تُقرأ من الموقع
alter table public.specializations_bk_20261009 enable row level security;
alter table public.study_plans_bk_20261009     enable row level security;
alter table public.subjects_bk_20261009        enable row level security;
alter table public.site_settings_bk_20261009   enable row level security;
alter table public.posts_bk_20261009           enable row level security;
revoke all on public.specializations_bk_20261009, public.study_plans_bk_20261009,
              public.subjects_bk_20261009, public.site_settings_bk_20261009,
              public.posts_bk_20261009 from anon, authenticated;

-- ② التخصصات السبعة
update public.specializations set
  summary           = $q$تخصص إنشاء هياكل السفن المعدنية وإصلاحها: قراءة رسومات البدن، وتخطيط الألواح وقصّها وتشكيلها، وتجميع الوحدات والقطاعات وضبط أبعادها.$q$,
  definition        = $q$يُعنى تخصص بناء السفن (البدن) بالأعمال التي يتكوّن بها هيكل السفينة المعدني: قراءة رسومات العمارة البحرية ورسومات الورشة، ونقل الأبعاد إلى الألواح والقطاعات بالتخطيط والتعليم، وقصّها وتشكيلها، ثم تجميعها في وحدات وقطاعات وضبط استقامتها وأبعادها قبل لحامها، ومتابعة الفحص البصري للقطاع بعد التجميع.$q$,
  importance        = $q$البدن هو الهيكل الذي تُبنى عليه السفينة كلها وتُركَّب عليه معداتها ومنظوماتها؛ ودقة تخطيطه وتجميعه تحدد متانته وقدرته على تحمّل أحمال البحر. وأعمال البدن هي النشاط الرئيسي في بناء السفن وإصلاحها بشركة ترسانة الإسكندرية.$q$,
  objectives        = $q$["تمكين المتعلم من قراءة رسومات البدن ورسومات الورشة وفهم رموزها وأبعادها", "إكسابه مهارة تخطيط الألواح والقطاعات المعدنية وقصّها وتشكيلها بدقة", "تدريبه على تجميع الوحدات والقطاعات وضبط استقامتها وأبعادها", "ترسيخ اشتراطات السلامة الخاصة بالأوزان الثقيلة والأحمال المرفوعة والعمل على ارتفاع"]$q$::jsonb,
  skills            = $q$["قراءة رسومات العمارة البحرية ورسومات الورشة", "التخطيط والتعليم ونقل الأبعاد على الألواح والقطاعات", "قص الألواح وتشكيلها", "تجميع الوحدات وضبط الاستقامة والأبعاد", "استخدام أدوات القياس والتحقق من مطابقة القطعة للرسم", "تأمين القطع قبل العمل عليها والتعامل الآمن مع أدوات الرفع"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة بناء السفن بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من قراءة الرسم والتخطيط على الألواح إلى القص والتشكيل، ثم إلى المشاركة في تجميع وحدات وقطاعات فعلية داخل ورش الشركة. محاذير خاصة بالورشة: عدم الوقوف أسفل الأحمال المرفوعة، واستخدام أدوات الرفع المعتمدة فقط، وتأمين القطع قبل العمل عليها.$q$,
  equipment         = $q$["مقص ذو رافعة", "مكبس يدوي", "التناية (ماكينة ثني)", "عدد اليد وأدوات التخطيط والتعليم", "أدوات القياس المعايرة"]$q$::jsonb,
  career_paths      = $q$["ورش بناء الهياكل وإصلاحها بأحواض بناء وإصلاح السفن", "ورش التشكيل المعدني والإنشاءات المعدنية", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يقرأ رسم قطاع من البدن ويستخرج منه الأبعاد وخطوات التنفيذ", "يخطّط لوحاً أو قطاعاً معدنياً وينقل إليه الأبعاد من الرسم", "يقص لوحاً ويشكّله بالأبعاد المطلوبة ويتحقق منها بأدوات القياس", "يشارك في تجميع وحدة أو قطاع ويضبط استقامته تحت إشراف المدرب", "يطبّق تعليمات السلامة الخاصة بالأحمال المرفوعة والعمل على ارتفاع دون مخالفة"]$q$::jsonb
where slug = 'shipbuilding';

update public.specializations set
  summary           = $q$تخصص تنفيذ التركيبات والدوائر الكهربائية وصيانتها على السفن وفي المنشآت الصناعية: من قراءة الرسم الكهربي إلى التمديد والتوصيل والقياس والاختبار.$q$,
  definition        = $q$يُعنى تخصص التركيبات الكهربائية بقراءة الرسومات والدوائر الكهربائية، وتمديد الأسلاك والكابلات وتوصيلها، وتركيب لوحات التوزيع وأجهزة الحماية، وتنفيذ دوائر التحكم الأساسية، وقياس الدوائر واختبارها بأجهزة القياس الكهربية وتحديد أعطالها البسيطة.$q$,
  importance        = $q$تعتمد منظومات السفينة كلها — من الإنارة والتهوية إلى المضخات والمعدات المساعدة — على تركيبات كهربائية سليمة ومحمية؛ ودقة التنفيذ والالتزام بإجراءات الفصل والعزل شرط لسلامة السفينة ومن يعمل عليها.$q$,
  objectives        = $q$["تمكين المتعلم من قراءة الرسم الكهربي والدوائر وتنفيذها", "إكسابه مهارة تمديد الأسلاك والكابلات وتوصيلها وتركيب اللوحات وأجهزة الحماية", "تدريبه على استخدام أجهزة القياس الكهربية في الفحص وتحديد الأعطال", "ترسيخ قاعدة فصل التيار والتأكد من فصله قبل أي عمل"]$q$::jsonb,
  skills            = $q$["قراءة الرسم الكهربي والدوائر", "تمديد الأسلاك والكابلات وتوصيلها", "تركيب لوحات التوزيع وأجهزة الحماية", "تنفيذ دوائر التحكم الأساسية", "القياس والاختبار بأجهزة القياس الكهربية", "تطبيق إجراءات الفصل والعزل ووضع لافتات التحذير"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة التركيبات الكهربائية ومعمل الكهرباء بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من أساسيات الكهرباء والخامات الكهربية إلى تمديد الدوائر وتركيب اللوحات، ثم إلى دوائر التحكم والقياس والاختبار. محاذير خاصة بالورشة: فصل التيار والتأكد من فصله قبل العمل، ووضع لافتة تحذير على القاطع، وعدم العمل على دوائر حية إطلاقاً.$q$,
  equipment         = $q$["كبائن تدريب على أعمال التمديدات الكهربية", "ماكيتات تدريب على أعمال التحكم الآلي", "معمل الكهرباء بالمركز", "أجهزة القياس الكهربية", "أدوات معزولة"]$q$::jsonb,
  career_paths      = $q$["ورش الكهرباء بأحواض بناء وإصلاح السفن", "أعمال صيانة التركيبات الكهربائية بالمنشآت الصناعية", "شركات المقاولات الكهربائية", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يقرأ رسماً كهربياً لدائرة إنارة أو قوى وينفّذه على كابينة التدريب", "يمدّد الأسلاك ويوصّلها ويركّب أجهزة الحماية وفق الرسم", "يقيس الجهد والتيار والمقاومة بجهاز القياس المناسب ويسجّل القراءة", "يحدّد عطلاً بسيطاً في دائرة تدريبية ويصلحه بعد فصل التيار", "يطبّق إجراءات الفصل والعزل والتحذير قبل كل عمل دون مخالفة"]$q$::jsonb
where slug = 'electrical-installations';

update public.specializations set
  summary           = $q$تخصص تركيب المعدات والأجزاء الميكانيكية وضبطها وصيانتها: البرادة والتجميع والفك والربط وضبط الاستقامة.$q$,
  definition        = $q$يُعنى تخصص التركيبات الميكانيكية بأعمال البرادة وتشغيل المعادن يدوياً، وقراءة الرسم الصناعي والمقايسات، وتجميع الأجزاء الميكانيكية وفكّها وربطها بالأدوات المناسبة، وضبط استقامة المعدات وخلوصاتها، والتعرّف على أساسيات المنظومات الهيدروليكية وصيانتها.$q$,
  importance        = $q$جودة التركيب الميكانيكي تحدد كفاءة المعدة وعمرها؛ فالخطأ في الاستقامة أو الخلوص أو الربط يظهر اهتزازاً وتآكلاً وعطلاً مبكراً. وتحتاج السفينة إلى فنيين يركّبون معداتها ومساعداتها ويصونونها بدقة.$q$,
  objectives        = $q$["إكساب المتعلم مهارات البرادة وتشغيل المعادن يدوياً", "تمكينه من قراءة الرسم الصناعي وتنفيذ القطع بالمقاسات المطلوبة", "تدريبه على التجميع والفك والربط وضبط الاستقامة والخلوصات", "ترسيخ اشتراطات السلامة الخاصة بالأجزاء المتحركة والضغط الهيدروليكي"]$q$::jsonb,
  skills            = $q$["البرادة والتخطيط والتثقيب", "قراءة الرسم الصناعي والمقايسات", "استخدام أدوات القياس للتحقق من المقاسات", "التجميع والفك والربط بالمفتاح المناسب لكل مقاس", "ضبط استقامة المعدات وخلوصاتها", "التعامل الآمن مع المنظومات الهيدروليكية بعد تفريغ الضغط"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة التركيبات الميكانيكية بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من تمارين البرادة والتثقيب إلى تجميع الأجزاء وفكّها، ثم إلى ضبط الاستقامة والمشاركة في تركيب معدات فعلية داخل ورش الشركة. محاذير خاصة بالورشة: تفريغ الضغط قبل الفك، واستخدام المفتاح المناسب لكل مقاس، وعدم استخدام وصلات إطالة غير معتمدة.$q$,
  equipment         = $q$["مثاقب (رأس · تزجه · مصانع · شجرة)", "ماكينات وأحجار تجليخ", "عدد اليد وأدوات البرادة والفك والربط", "أدوات القياس المعايرة"]$q$::jsonb,
  career_paths      = $q$["ورش التركيبات الميكانيكية بأحواض بناء وإصلاح السفن", "أقسام صيانة المعدات بالمصانع", "شركات التركيبات الصناعية", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["ينفّذ قطعة برادة بالمقاسات الواردة في الرسم ويتحقق منها بأدوات القياس", "يقرأ رسم تجميع ويحدّد منه ترتيب الأجزاء وخطوات التركيب", "يجمّع مجموعة ميكانيكية ويفكّها ويربطها بالأدوات الصحيحة", "يضبط استقامة عمود أو معدة تدريبية تحت إشراف المدرب", "يطبّق اشتراطات السلامة الميكانيكية ويفرّغ الضغط قبل الفك"]$q$::jsonb
where slug = 'mechanical-installations';

update public.specializations set
  summary           = $q$تخصص لحام المعادن وقطعها حرارياً: تجهيز الوصلات، واللحام بالقوس الكهربي وبالغاز في الأوضاع المختلفة، والقطع بالغاز، والفحص البصري للحامات.$q$,
  definition        = $q$يُعنى تخصص اللحام والقطع بالغاز بتجهيز الأسطح والوصلات، وضبط ماكينة اللحام واختيار السلك أو القطب المناسب، وتنفيذ اللحام بالقوس الكهربي واللحام بالغاز في الأوضاع المختلفة، والقطع الحراري بالغاز، ثم فحص اللحامة بصرياً وتمييز عيوبها الظاهرة.$q$,
  importance        = $q$اللحام هو ما يربط ألواح البدن وقطاعاته ومواسيره في هيكل واحد محكم؛ وجودة اللحامة تعني متانة الهيكل وإحكامه، وعيبها قد يعني تسريباً أو شرخاً. ولذلك يحتاج كل حوض لبناء السفن وإصلاحها إلى لحّامين مدرَّبين وملتزمين بالسلامة.$q$,
  objectives        = $q$["إكساب المتعلم مهارة تجهيز الوصلات وضبط ماكينات اللحام", "تدريبه على اللحام بالقوس الكهربي وبالغاز في الأوضاع المقررة", "تمكينه من القطع الحراري بالغاز بأمان", "ترسيخ اشتراطات سلامة اللحام والتهوية والتعامل مع الأسطوانات"]$q$::jsonb,
  skills            = $q$["تجهيز الأسطح والوصلات قبل اللحام", "ضبط ماكينة اللحام واختيار السلك أو القطب المناسب", "اللحام بالقوس الكهربي ولحام CO2", "اللحام والقطع بالغاز", "الفحص البصري للحامات وتمييز عيوبها الظاهرة", "التعامل الآمن مع الأسطوانات والمنظمات والخراطيم"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة اللحام والقطع بالغاز بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من تجهيز الوصلات واللحام في الوضع الأفقي إلى الأوضاع الأصعب، مع تمارين القطع بالغاز، ثم إلى المشاركة في أعمال لحام فعلية داخل ورش الشركة. محاذير خاصة بالورشة: التأكد من إحكام وصلات الأسطوانات وتثبيتها رأسياً، والتهوية الجيدة، وإبعاد المواد القابلة للاشتعال، وفحص المنطقة بعد انتهاء العمل.$q$,
  equipment         = $q$["ماكينات لحام CO2 طراز PANASONIC", "ماكينات لحام Miller", "ماكينات لحام HEDO DH ZXEL-500", "ماكينات لحام ESAB T.H.F", "وحدة لحام متحركة"]$q$::jsonb,
  career_paths      = $q$["أعمال اللحام بأحواض بناء وإصلاح السفن", "ورش الإنشاءات المعدنية", "تصنيع الخزانات وخطوط المواسير", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يجهّز وصلة للحام ويضبط الماكينة على الإعدادات المناسبة لسمك المعدن", "ينفّذ خط لحام مقبولاً في الأوضاع المقررة لكل صف", "يقطع لوحاً بالغاز على خط مرسوم بأمان", "يميّز عيوب اللحام الظاهرة بالفحص البصري ويحدّد سببها المحتمل", "يطبّق تعليمات سلامة اللحام والأسطوانات ويرتدي مهمات الوقاية كاملة"]$q$::jsonb
where slug = 'welding-gas-cutting';

update public.specializations set
  summary           = $q$تخصص تشغيل المعادن على الماكينات — الخراطة والفرايز والمقاشط — لإنتاج القطع بالأبعاد والتفاوتات المطلوبة في الرسم.$q$,
  definition        = $q$يُعنى تخصص التشغيل على الماكينات بضبط ماكينات الخراطة والفرايز والمقاشط وتشغيلها، واختيار عدة القطع وسرعات القطع والتغذية المناسبة، وإنتاج القطع طبقاً للرسم الصناعي والتفاوتات المطلوبة، وقياسها بأدوات القياس الدقيقة.$q$,
  importance        = $q$كثير من قطع الغيار والأجزاء التي تحتاجها السفينة ومعداتها يُصنَّع أو يُعاد تشغيله على الماكينات؛ ودقة التشغيل والقياس هي ما يجعل القطعة صالحة للتركيب والعمل.$q$,
  objectives        = $q$["إكساب المتعلم مهارة ضبط ماكينات التشغيل وتشغيلها بأمان", "تدريبه على اختيار العدة وسرعات القطع والتغذية", "تمكينه من إنتاج قطع مطابقة للرسم والتفاوتات وقياسها بدقة", "ترسيخ اشتراطات السلامة على الماكينات الدوارة"]$q$::jsonb,
  skills            = $q$["ضبط ماكينة الخراطة وتشغيلها", "التشغيل على الفرايز والمقاشط", "قراءة الرسم الصناعي والتفاوتات", "اختيار عدة القطع وسرعات القطع والتغذية", "القياس بالقدمة ذات الورنية وأدوات القياس الدقيقة", "إيقاف الماكينة قبل القياس أو التنظيف والتعامل الآمن مع الرايش"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة التشغيل على الماكينات بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من عمليات الخراطة الأساسية إلى العمليات الأدق على الفرايز والمقاشط، ثم إلى المشاركة في تشغيل قطع فعلية داخل ورش الشركة. محاذير خاصة بالورشة: منع القفاز أثناء التشغيل على الماكينات الدوارة، وإيقاف الماكينة قبل القياس أو التنظيف، وعدم إزالة الرايش باليد.$q$,
  equipment         = $q$["مخارط (روسي · مصانع حربي · متعددة الأغراض · جامعة الأغراض)", "مقاشط 500 مم", "ماكينات تجليخ (أسطواني · متعددة الأغراض · سن بنط التثقيب)", "أدوات القياس الدقيقة المعايرة"]$q$::jsonb,
  career_paths      = $q$["ورش التشغيل بأحواض بناء وإصلاح السفن", "ورش تصنيع قطع الغيار", "المصانع الهندسية", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يضبط المخرطة ويشغّلها بأمان لتنفيذ عملية خراطة خارجية", "يختار عدة القطع وسرعة القطع والتغذية المناسبة للخامة", "ينتج قطعة مطابقة لأبعاد الرسم في حدود التفاوت المطلوب", "يقيس القطعة بالقدمة ذات الورنية ويسجّل نتيجة القياس", "يطبّق قواعد السلامة على الماكينات الدوارة دون مخالفة"]$q$::jsonb
where slug = 'machining';

update public.specializations set
  summary           = $q$تخصص تجهيز خطوط المواسير وتركيبها على السفن وفي المنشآت الصناعية: القياس والقص والثني وتجهيز الوصلات والتركيب واختبار الإحكام.$q$,
  definition        = $q$يُعنى تخصص برادة خطوط المواسير بقراءة رسومات الخطوط، وقياس المواسير وقصّها وثنيها، وتجهيز أطرافها ووصلاتها وفلانشاتها، وتركيب الخطوط والدعامات، والمشاركة في اختبار إحكام الخط بعد تركيبه.$q$,
  importance        = $q$خطوط المواسير تنقل الوقود والزيوت والمياه والهواء داخل السفينة؛ وأي خطأ في القياس أو الثني أو الوصلة قد يسبب تسريباً يوقف المنظومة أو يهدد السلامة.$q$,
  objectives        = $q$["تمكين المتعلم من قراءة رسومات خطوط المواسير", "إكسابه مهارة قياس المواسير وقصّها وثنيها وتجهيز وصلاتها", "تدريبه على تركيب الخطوط والدعامات والمشاركة في اختبار الإحكام", "ترسيخ اشتراطات السلامة أثناء القص والمناولة والتركيب"]$q$::jsonb,
  skills            = $q$["قراءة رسومات خطوط المواسير", "قياس المواسير وقصّها", "ثني المواسير يدوياً وآلياً", "تجهيز الوصلات والفلانشات وإزالة الحواف الحادة", "تركيب الخطوط والدعامات", "المشاركة في اختبار إحكام الخطوط"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة برادة خطوط المواسير بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من القياس والقص وتجهيز الأطراف إلى الثني وتجميع الوصلات، ثم إلى المشاركة في تركيب خطوط فعلية داخل ورش الشركة. محاذير خاصة بالورشة: تثبيت الماسورة جيداً قبل البرد أو القطع، وإزالة الحواف الحادة فور القطع.$q$,
  equipment         = $q$["ماكينة ثني مواسير", "ماكينة ثني مواسير يدوية", "منشار ميكانيكي", "عدد اليد وأدوات البرادة", "أدوات القياس المعايرة"]$q$::jsonb,
  career_paths      = $q$["ورش المواسير بأحواض بناء وإصلاح السفن", "أعمال خطوط المواسير بالمصانع والمنشآت الصناعية", "شركات المقاولات الميكانيكية", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يقرأ رسم خط مواسير ويستخرج منه الأطوال وزوايا الثني", "يقيس ماسورة ويقصّها ويجهّز طرفها بالمقاس المطلوب", "يثني ماسورة بالزاوية المطلوبة ويتحقق منها", "يجمّع وصلة أو فلانشة ويركّب جزءاً من خط تحت إشراف المدرب", "يطبّق تعليمات السلامة الخاصة بالقص والمناولة دون مخالفة"]$q$::jsonb
where slug = 'pipe-fitting';

update public.specializations set
  summary           = $q$تخصص محركات الديزل ومنظوماتها: مبدأ عمل المحرك ومكوناته، والفك والتجميع والضبط، والصيانة الوقائية لمنظومات الوقود والتزييت والتبريد.$q$,
  definition        = $q$يُعنى تخصص الديزل بمكونات محرك الديزل ومبدأ عمله، ومنظومات الوقود والتزييت والتبريد وبدء الحركة، وأعمال الفك والتجميع والضبط وفق تعليمات الصانع، والصيانة الوقائية للمحرك ومساعداته، وتحديد الأعطال الشائعة.$q$,
  importance        = $q$محركات الديزل هي مصدر الدفع وتوليد الكهرباء في أغلب السفن؛ وانتظام صيانتها ودقة ضبطها شرط لتشغيل السفينة وسلامة رحلتها.$q$,
  objectives        = $q$["تمكين المتعلم من فهم مكونات محرك الديزل ومبدأ عمله", "تدريبه على الفك والتجميع والضبط وفق تعليمات الصانع", "إكسابه مهارات الصيانة الوقائية لمنظومات الوقود والتزييت والتبريد", "ترسيخ اشتراطات السلامة عند العمل على المحركات"]$q$::jsonb,
  skills            = $q$["التعرف على مكونات محرك الديزل ومنظوماته", "الفك والتجميع والضبط وفق تعليمات الصانع", "صيانة منظومات الوقود والتزييت والتبريد", "تحديد الأعطال الشائعة", "استخدام أدوات القياس في الفحص والضبط", "العمل الآمن على المحرك بعد تبريده والتعامل مع الانسكابات"]$q$::jsonb,
  training_nature   = $q$في الصف الأول يتدرّب المتعلم داخل ورشة الديزل بالمركز على تمارين تأسيسية تحت الإشراف المباشر للمدرب، ولا يبدأ أي تمرين إلا بعد توعية بتعليمات السلامة الخاصة به. وفي الصفين الثاني والثالث يمتد التدريب إلى ورش شركة ترسانة الإسكندرية الإنتاجية بقطاعي بناء السفن والأعمال الهندسية، ويُوزَّع المتعلمون عليها وفق معدل التوزيع المعتمد لكل قسم، ويقيّم المهندس أو الملاحظ المسؤول أداءهم يومياً. ولا يُكلَّف المتعلم بأي عمل يتجاوز مقرر تدريبه أو يخالف ضوابط تدريب من هم دون الثامنة عشرة. ويتدرّج التدريب من التعرف على مكونات المحرك وأدوات العمل إلى الفك والتجميع والضبط، ثم إلى الصيانة الوقائية والمشاركة في أعمال على محركات فعلية داخل ورش الشركة. محاذير خاصة بالورشة: عدم بدء العمل قبل تبريد المحرك، وتنظيف الانسكابات فوراً، والتهوية أثناء تشغيل المحرك.$q$,
  equipment         = $q$["عدد اليد وأدوات الفك والتجميع والضبط", "أدوات القياس المعايرة"]$q$::jsonb,
  career_paths      = $q$["أقسام المحركات بأحواض بناء وإصلاح السفن", "ورش صيانة المحركات", "صيانة المولدات ومحطات التوليد", "استكمال الدراسة بالتقدم للتنسيق وفق القواعد المعلنة"]$q$::jsonb,
  learning_outcomes = $q$["يحدّد مكونات محرك الديزل ويشرح دور كل منظومة", "يفك مجموعة من المحرك ويجمّعها بالترتيب الصحيح وفق التعليمات", "ينفّذ مهمة صيانة وقائية على منظومة الوقود أو التزييت أو التبريد", "يستخدم أدوات القياس في فحص الأجزاء وتسجيل القراءات", "يطبّق تعليمات السلامة الخاصة بالمحركات دون مخالفة"]$q$::jsonb
where slug = 'diesel';

