-- ④ مادة «أجهزة قياس» للصف الأول — واردة بالدليل ISO-COM-MN-01 (9-1) وغير ظاهرة حالياً
insert into public.subjects (name, grade_id, specialization_id, is_common, kind, sort_order, is_published)
values ('أجهزة قياس', 1, null, true, 'general', 1, true)
on conflict (name, grade_id, specialization_id) do update set is_published = true, sort_order = 1;

-- ⑤ تصحيحات نصية في إعدادات الموقع
-- الرؤية: حذف علامة تنصيص زائدة في آخر النص
update public.site_settings
   set value = to_jsonb(rtrim(rtrim(value #>> '{}'), '"'))
 where key = 'about.vision' and (value #>> '{}') like '%"';

-- ⑥ خبر مواعيد بدء الدراسة: تصحيح «لصطلاب» و«بدايه» وتوحيد صيغة التاريخ
update public.posts set
  excerpt = $q$مواعيد بدء الدراسة لطلاب مركز التدريب للعام الدراسي 2026/2027.$q$,
  body    = $q$• الصف الثالث: السبت 26/9/2026
• الصف الثاني: الاثنين 28/9/2026
• الصف الأول: السبت 3/10/2026$q$
where slug = 'sample-news' and title = 'مواعيد بدء الدراسة بالمركز';

-- ⑦ فحص قبل الاعتماد: لا يبقى أي نص «[يتم تحديث …]» في التخصصات
do $$
declare n int;
begin
  select count(*) into n from public.specializations
   where (to_jsonb(specializations)::text) like '%[يتم تحديث%';
  if n > 0 then raise exception 'ما زال % تخصص يحتوي على نص مؤقت', n; end if;
  select count(*) into n from public.specializations where updated_at > now() - interval '1 minute';
  if n <> 7 then raise exception 'المتوقع تحديث 7 تخصصات، والذي تحدّث %', n; end if;
end $$;

commit;

